   750	    if (!kind) return;
   751	    const rules = params.rulesByKind[kind];
   752	    if (!rules) return;
   753	    for (const rule of rules) {
   754	      const link = extractLink(item, rule);
   755	      if (!link) continue;
   756	      // Metadata stamping is deferred to post-resolution (below) — only
   757	      // attached identifiers are stamped, so a stale one (e.g. a vacated
   758	      // github_login) can't make read-time JOINs attribute to the wrong person.
   759	      let bucket = byRule.get(rule);
   760	      if (!bucket) {
   761	        bucket = [];
   762	        byRule.set(rule, bucket);
   763	      }
   764	      bucket.push({ index, item, link });
   765	    }
   766	  });
   767	  if (byRule.size === 0) return resolvedByItem;
   768	
   769	  const recordResolved = (index: number, entityId: number): void => {
   770	    const existing = resolvedByItem.get(index);
   771	    if (existing) {
   772	      if (!existing.includes(entityId)) existing.push(entityId);
   773	    } else {
   774	      resolvedByItem.set(index, [entityId]);
   775	    }
   776	  };
   777	
   778	  for (const [rule, entries] of byRule) {
   779	    const matches = await lookupMatches(sql, {
   780	      orgId: params.orgId,
   781	      identities: entries.map((e) => e.link.identities),
   782	    });
   783	
   784	    for (const { index, item, link } of entries) {
   785	      // Tier semantics are defined once in `resolveIdentityTier` and shared
   786	      // with the orphan-recovery re-resolution below. A present primary that
   787	      // matched nothing resolves to null here on purpose: the create path then
   788	      // mints a new entity keyed on it instead of absorbing a stale
   789	      // secondary's owner.
   790	      const tier = resolveIdentityTier(link.identities, matches);
   791	      const ambiguous = tier === 'ambiguous';
   792	      let entityId: number | null = ambiguous ? null : tier;
   793	      let isCreate = false;
   794	
   795	      if (ambiguous) {
   796	        logger.warn(
   797	          {
   798	            orgId: params.orgId,
   799	            connectorKey: params.connectorKey,
   800	            entityType: rule.entityType,
   801	            identifiers: link.identities.map((i) => `${i.namespace}:${i.identifier}`),
   802	          },
   803	          'entityLink merge candidate — multiple entities matched at the same identity tier'
   804	        );
   805	        continue;
   806	      }
   807	
   808	      // Identities that ACTUALLY attached to the resolved/created entity. We
   809	      // only ever claim THESE in the in-memory matches map below — an identifier
   810	      // that ON CONFLICT-skipped because another entity already owns it stays
   811	      // with that entity, so the map must not mis-claim it for this one.
   812	      let attached: Array<{ namespace: string; identifier: string }> = [];
   813	      if (entityId !== null) {
   814	        // Matched an existing entity: accrete the non-matchOnly identities; the
   815	        // identifier(s) we matched on already belong to this entity.
   816	        const fresh = await insertIdentities(sql, {
   817	          orgId: params.orgId,
   818	          entityId,
   819	          connectorKey: params.connectorKey,
   820	          connectionId: params.connectionId,
   821	          identities: link.identities.filter((i) => !i.matchOnly),
   822	        });
   823	        attached = [...fresh];
   824	        // Mirror this link's non-matchOnly identifiers into metadata.aliases for
   825	        // metric resolution. Passing the full set (not just `fresh`) repairs a
   826	        // legacy entity whose identities predate aliases-on-create; ensureAliases'
   827	        // `@>` guard makes it a no-op write once the aliases are complete, so a
   828	        // repeat message from a known sender stays cheap.
   829	        await ensureAliases(sql, {
   830	          orgId: params.orgId,
   831	          entityId,
   832	          identifiers: link.identities.filter((i) => !i.matchOnly).map((i) => i.identifier),
   833	        });
   834	        // The matched identifiers themselves are this entity's even if a
   835	        // re-insert was a no-op (they were how we found it), so claim them too.
   836	        for (const id of link.identities) {
   837	          if (matches.get(`${id.namespace}\u0000${id.identifier}`) === entityId) {
   838	            attached.push({ namespace: id.namespace, identifier: id.identifier });
   839	          }
   840	        }
   841	      } else if (rule.autoCreate && passesCreateWhen(rule.createWhen, item)) {
   842	        if (!creatorUserId) {
   843	          logger.warn(
   844	            { orgId: params.orgId, entityType: rule.entityType },
   845	            'autoCreate skipped: org has no member to attribute as creator'
   846	          );
   847	          continue;
   848	        }
   849	        const created = await createEntityWithIdentities(sql, {
   850	          orgId: params.orgId,
   851	          connectorKey: params.connectorKey,
   852	          connectionId: params.connectionId,
   853	          entityType: rule.entityType,
   854	          title: link.title,
   855	          identities: link.identities,
   856	          traits: link.traits,
   857	          creatorUserId,
   858	        });
   859	        if (created !== null && created.attached.length > 0) {
   860	          entityId = created.entityId;
   861	          attached = created.attached;
   862	          isCreate = true;
   863	        } else if (created !== null) {
   864	          // Concurrent auto-create lost the identity race: every identifier went
   865	          // to the winner via ON CONFLICT, so the row we just inserted is an
   866	          // identity-less orphan. Hard-delete it (no events reference a row born
   867	          // this turn) and re-resolve to the winning entity.
   868	          await sql`
   869	            DELETE FROM entities
   870	            WHERE id = ${created.entityId} AND organization_id = ${params.orgId}
   871	          `;
   872	          const winner = await lookupMatches(sql, {
   873	            orgId: params.orgId,
   874	            identities: [link.identities],
   875	          });
   876	          // Re-resolve through the SAME tier rule as the ordinary lookup. A
   877	          // tier-blind union here mis-resolved when the primary's owner was
   878	          // soft-deleted (so the primary matched nothing) while a live entity
   879	          // still held a recycled secondary claim: the union saw exactly one
   880	          // hit and adopted the recycled-claim holder. `member_of` is a read
   881	          // ACL, so that granted one person another person's channel access.
   882	          // Unmatched-primary and ambiguous both leave entityId null → skip,
   883	          // which fails closed (no edge) rather than guessing an owner.
   884	          const winnerTier = resolveIdentityTier(link.identities, winner);
   885	          if (typeof winnerTier === 'number') {
   886	            entityId = winnerTier;
   887	            for (const id of link.identities) {
   888	              if (winner.get(`${id.namespace}\u0000${id.identifier}`) === entityId) {
   889	                attached.push({ namespace: id.namespace, identifier: id.identifier });
   890	              }
   891	            }
   892	          }
   893	        }
   894	      }
   895	
   896	      if (entityId === null) continue;
   897	
   898	      await applyTraits(sql, {
   899	        orgId: params.orgId,
   900	        entityId,
   901	        rule,
   902	        traits: link.traits,
   903	        isCreate,
   904	      });
   905	
   906	      recordResolved(index, entityId);
   907	
   908	      // Cache the mapping for later items in the same batch — only for attached
   909	      // identifiers, so an identifier that stayed on another entity (ON CONFLICT
   910	      // no-op) keeps its existing owner and isn't mis-claimed.
   911	      for (const id of attached) {
   912	        matches.set(`${id.namespace}\u0000${id.identifier}`, entityId);
   913	      }
   914	
   915	      // Stamp metadata slots for attached identifiers only — read-time JOINs key
   916	      // on events.metadata->>namespace, so a stale slot would mis-attribute.
   917	      //
   918	      // A namespace slot holds ONE value, but an event can carry multiple
   919	      // attribution rules that resolve the SAME namespace to DIFFERENT entities
   920	      // (e.g. an X DM stamps x_user_id for both the `authored_by` sender and the
   921	      // `about` counterparty). Read-time recall can only match one of them via
   922	      // this slot, so first-writer-wins: the earliest-declared rule (the primary
   923	      // author) keeps the slot, and we log the collision so the case that needs a
   924	      // richer, role-aware read model is observable rather than silently dropped.
   925	      // Making role queryable at read time is deliberately a separate change (it
   926	      // touches the shared recall SQL + every call site) — until then this is the
   927	      // honest boundary, not a workaround.
   928	      const md = (item.metadata ??= {});
   929	      for (const id of attached) {
   930	        const existing = md[id.namespace];
   928	      const md = (item.metadata ??= {});
   929	      for (const id of attached) {
   930	        const existing = md[id.namespace];
   931	        if (existing !== undefined && existing !== id.identifier) {
   932	          logger.warn(
   933	            {
   934	              orgId: params.orgId,
   935	              connectorKey: params.connectorKey,
   936	              namespace: id.namespace,
   937	              kept: existing,
   938	              dropped: id.identifier,
   939	              role: rule.role,
   940	            },
   941	            'attribution metadata slot collision — a later rule resolved the same namespace to a different identifier; keeping the first-stamped value (read-time recall matches only one)'
   942	          );
   943	          continue;
   944	        }
   945	        md[id.namespace] = id.identifier;
   946	      }
   947	    }
   948	  }
   949	
   950	  return resolvedByItem;
   951	}
   952	
   953	/**
   954	 * Resolve the SENDER of a captured chat message to an entity id — STORE-ONLY
   955	 * attribution for `channel_messages.author_entity_id`. Connector-AGNOSTIC: the
   956	 * caller hands over an already-normalized identity spec (it owns the platform's
   957	 * namespace + normalizer) and the entity type to mint on a miss; this function
   958	 * names no connector.
   959	 *
   960	 * Unlike {@link applyEventAttributions}, this writes NO event row, stamps no
   961	 * `events.metadata`, and never enters the embed pipeline: it only reads the
   962	 * normalized identity index and, on a miss, mints the given type (gated).
   963	 * Transcript is high-volume operational data, so the caller fire-and-forgets
   964	 * this — a resolution failure must never block capture or a webhook ack.
   965	 *
   966	 * Resolution (type-agnostic, driven by the #1646 cross-source collapse — a
   967	 * signed-in human is a `$member` carrying the same team-scoped chat identity):
   968	 *   1. the existing entity of ANY type owning this identity (a signed-in
   969	 *      `$member`, an already-attributed `person`, …) — return it. A single
   970	 *      {@link lookupMatches} covers all types because an identity value is
   971	 *      globally unique to one entity; no `$member`-before-`person` ordering.
   972	 *      Never mint a `$member` here (membership provisioning owns that, so
   973	 *      attribution and ACL converge on the SAME entity).
   974	 *   2. else mint `mintEntityType`, gated on a well-formed identity + a real org
   975	 *      member to attribute the create to. Callers drop bots and malformed ids
   976	 *      BEFORE calling (an empty `identities` list → null).
   977	 */
   978	export async function resolveSenderIdentity(
   979	  sql: DbClient,
   980	  params: {
   981	    orgId: string;
   982	    connectorKey: string;
   983	    mintEntityType: string;
   984	    identities: ResolvedIdentity[];
   985	    title?: string | null;
   986	  }
   987	): Promise<number | null> {
   988	  if (params.identities.length === 0) return null;
   989	
   990	  const firstHit = (matches: Map<string, number>): number | null => {
   991	    for (const id of params.identities) {
   992	      const hit = matches.get(`${id.namespace}\u0000${id.identifier}`);
   993	      if (hit !== undefined) return hit;
   994	    }
   995	    return null;
   996	  };
   997	
   998	  // 1) Any existing entity owning this identity — $member (signed-in human,
   999	  // #1646) or person, resolved by one type-agnostic lookup. No create.
  1000	  const hit = firstHit(
  1001	    await lookupMatches(sql, { orgId: params.orgId, identities: [params.identities] })
  1002	  );
  1003	  if (hit !== null) return hit;
  1004	
  1005	  // 2) Mint. The only remaining gate is a real org member to attribute to.
  1006	  const creatorUserId = await resolveOrgCreator(params.orgId);
  1007	  if (!creatorUserId) return null;
  1008	
  1009	  const created = await createEntityWithIdentities(sql, {
  1010	    orgId: params.orgId,
  1011	    connectorKey: params.connectorKey,
  1012	    entityType: params.mintEntityType,
  1013	    title: params.title?.trim() || '',
  1014	    identities: params.identities,
  1015	    traits: new Map(),
  1016	    creatorUserId,
  1017	  });
  1018	  if (created !== null && created.attached.length > 0) {
  1019	    return created.entityId;
  1020	  }
  1021	  // Lost the identity create-race (a concurrent ingest minted it first): drop
  1022	  // the identity-less orphan and resolve to the winner instead.
  1023	  if (created !== null) {
  1024	    await sql`
  1025	      DELETE FROM entities
  1026	      WHERE id = ${created.entityId} AND organization_id = ${params.orgId}
  1027	    `;
  1028	    return firstHit(
  1029	      await lookupMatches(sql, { orgId: params.orgId, identities: [params.identities] })
  1030	    );
  1031	  }
  1032	  return null;
  1033	}

