411	async function createEntityWithIdentities(
412	  sql: DbClient,
413	  params: {
414	    orgId: string;
415	    connectorKey: string;
416	    connectionId?: number | null;
417	    entityType: string;
418	    title: string;
419	    identities: ExtractedLink['identities'];
420	    traits: Map<string, unknown>;
421	    creatorUserId: string;
422	  }
423	): Promise<{ entityId: number; attached: Array<{ namespace: string; identifier: string }> } | null> {
424	  const persisted = params.identities.filter((i) => !i.matchOnly);
425	  if (persisted.length === 0) return null;
426	
427	  const name = params.title || persisted[0].identifier;
428	  const metadata: Record<string, unknown> = {};
429	  for (const [key, value] of params.traits) metadata[key] = value;
430	
431	  // Resolve entity_type slug → entity_types(id). Same schema search path as
432	  // createEntity: try the entity's own org first, then any visibility='public'
433	  // catalog. First match wins. See createEntity for the slug-poisoning caveat.
434	  let typeRow = await sql<{ id: number; backing_sql: string | null }>`
435	    SELECT et.id, et.backing_sql
436	    FROM entity_types et
437	    LEFT JOIN organization o ON o.id = et.organization_id
438	    WHERE et.slug = ${params.entityType}
439	      AND et.deleted_at IS NULL
440	      AND (
441	        et.organization_id = ${params.orgId}
442	        OR o.visibility = 'public'
443	      )
444	    ORDER BY (et.organization_id = ${params.orgId}) DESC, et.id ASC
445	    LIMIT 1
446	  `;
447	  if (typeRow.length === 0) {
448	    // Platform ACL type is ensured on the fly so event attribution can race
449	    // ahead of the first ACL sync without failing closed on a missing type.
450	    if (params.entityType === ACL_RESOURCE_TYPE_SLUG) {
451	      await ensureResourceEntityType(params.orgId);
452	      typeRow = await sql<{ id: number; backing_sql: string | null }>`
453	        SELECT et.id, et.backing_sql
454	        FROM entity_types et
455	        WHERE et.slug = ${params.entityType}
456	          AND et.deleted_at IS NULL
457	          AND et.organization_id = ${params.orgId}
458	        LIMIT 1
459	      `;
460	      if (typeRow.length === 0) {
461	        logger.warn(
462	          { entityType: params.entityType, orgId: params.orgId },
463	          'entity create failed: $resource type ensure did not materialize'
464	        );
465	        return null;
466	      }
467	    } else {
468	      logger.warn(
469	        { entityType: params.entityType, orgId: params.orgId },
470	        'entity create failed: unknown entity type'
471	      );
472	      return null;
473	    }
474	  }
475	  // Derived (view-backed) types have no stored rows — skip auto-create (the
476	  // view ignores any row this would insert). Mirrors createEntity's guard for
477	  // this separate connector/link insert path.
478	  if (typeRow[0].backing_sql) {
479	    logger.warn(
480	      { entityType: params.entityType, orgId: params.orgId },
481	      'entity auto-create skipped: entity type is derived (a SQL view)'
482	    );
483	    return null;
484	  }
485	  const entityTypeId = typeRow[0].id;
486	
487	  // Try a few slug variants to defuse improbable random collisions.
488	  let entityId: number | null = null;
489	  for (let attempt = 0; attempt < 3 && entityId === null; attempt++) {
490	    const slug = randomSlug(params.entityType);
491	    try {
492	      const rows = await sql<{ id: number | string }>`
493	        INSERT INTO entities (
494	          organization_id, entity_type_id, name, slug, metadata,
495	          created_by, created_at, updated_at
496	        )
497	        VALUES (
498	          ${params.orgId}, ${entityTypeId}, ${name}, ${slug},
499	          ${sql.json(metadata)},
500	          ${params.creatorUserId}, current_timestamp, current_timestamp
501	        )
502	        ON CONFLICT DO NOTHING
503	        RETURNING id
504	      `;
505	      if (rows.length > 0) entityId = Number(rows[0].id);
506	    } catch (err) {
507	      logger.warn({ err, entityType: params.entityType }, 'entity create failed');
508	    }
509	  }
510	  if (entityId === null) return null;
511	
512	  const attached = await insertIdentities(sql, {
513	    orgId: params.orgId,
514	    entityId,
515	    connectorKey: params.connectorKey,
516	    connectionId: params.connectionId,
517	    identities: persisted,
518	  });
519	  // Seed metadata.aliases from the identifiers that actually attached, so the
520	  // metric compiler (which resolves event fields against metadata->'aliases')
521	  // can attribute this contact's events from the moment it's created.
522	  await ensureAliases(sql, {
523	    orgId: params.orgId,
524	    entityId,
525	    identifiers: attached.map((a) => a.identifier),
526	  });
527	  return { entityId, attached };
528	}
529	
530	/**
531	 * Insert identities for `entityId`, RETURNING the `(namespace, identifier)` rows
532	 * attached to that entity. Re-observing a legacy row fills missing connection
533	 * provenance; a row owned by another entity is not returned, so the caller will
534	 * not mis-claim it.
535	 */
536	async function insertIdentities(
537	  sql: DbClient,
538	  params: {
539	    orgId: string;
540	    entityId: number;
541	    connectorKey: string;
542	    connectionId?: number | null;
543	    identities: ExtractedLink['identities'];
544	  }
545	): Promise<Array<{ namespace: string; identifier: string }>> {
546	  if (params.identities.length === 0) return [];
547	  const namespaces = params.identities.map((i) => i.namespace);
548	  const identifiers = params.identities.map((i) => i.identifier);
549	  try {
550	    const attached = await sql<{ namespace: string; identifier: string }>`
551	      INSERT INTO entity_identities (
552	        organization_id, entity_id, namespace, identifier, source_connector, connection_id
553	      )
554	      SELECT ${params.orgId}, ${params.entityId}, v.ns, v.ident,
555	             ${`connector:${params.connectorKey}`}, ${params.connectionId ?? null}
556	      FROM unnest(${pgTextArray(namespaces)}::text[], ${pgTextArray(identifiers)}::text[]) AS v(ns, ident)
557	      ON CONFLICT (organization_id, namespace, identifier) WHERE deleted_at IS NULL
558	      DO UPDATE SET connection_id = EXCLUDED.connection_id
559	      WHERE entity_identities.entity_id = EXCLUDED.entity_id
560	        AND entity_identities.connection_id IS NULL
561	        AND EXCLUDED.connection_id IS NOT NULL
562	      RETURNING namespace, identifier
563	    `;
564	    return attached.map((r) => ({ namespace: r.namespace, identifier: r.identifier }));
565	  } catch (err) {
566	    logger.warn({ err, entityId: params.entityId }, 'entity_identities insert failed');
567	    return [];
568	  }
569	}
570	
571	async function applyTraits(
572	  sql: DbClient,
573	  params: {
574	    orgId: string;
575	    entityId: number;
576	    rule: ResolvedEventAttributionRule;
577	    traits: Map<string, unknown>;
578	    isCreate: boolean;
579	  }
580	): Promise<void> {
581	  if (!params.rule.traits || params.traits.size === 0) return;
582	
583	  // init_only traits were written to metadata at create time; nothing to do now.
584	  const overwrite: Record<string, unknown> = {};
585	  const preferNonEmpty: Record<string, unknown> = {};
586	  for (const [key, value] of params.traits) {
587	    const spec = params.rule.traits[key];
588	    if (!spec || spec.behavior === 'init_only') continue;
589	    if (value === undefined) continue;
590	    if (spec.behavior === 'overwrite') {
591	      overwrite[key] = value;
592	    } else if (spec.behavior === 'prefer_non_empty') {
593	      const empty = value === null || value === '';
594	      if (!empty) preferNonEmpty[key] = value;
595	    }
596	  }
597	  if (Object.keys(overwrite).length === 0 && Object.keys(preferNonEmpty).length === 0) return;
598	
599	  // Read-modify-write the metadata jsonb. A single worker processes a given
600	  // (connector, run) batch sequentially, so intra-batch races are impossible;
601	  // cross-batch races touching the same entity are rare enough to accept
602	  // last-writer-wins.
603	  const rows = await sql<{ metadata: Record<string, unknown> | null }>`
604	    SELECT metadata
605	    FROM entities
606	    WHERE id = ${params.entityId}
607	      AND organization_id = ${params.orgId}
608	      AND deleted_at IS NULL
609	    LIMIT 1
610	  `;
611	  if (rows.length === 0) return;
612	  const current = rows[0].metadata ?? {};
613	
614	  const next: Record<string, unknown> = { ...current, ...overwrite };
615	  for (const [key, value] of Object.entries(preferNonEmpty)) {
616	    const existing = current[key];
617	    if (existing === undefined || existing === null || existing === '') {
618	      next[key] = value;
619	    }
620	  }
621	
622	  await sql`
623	    UPDATE entities
624	    SET metadata = ${sql.json(next)},
625	        updated_at = current_timestamp
626	    WHERE id = ${params.entityId}
627	      AND organization_id = ${params.orgId}
628	      AND deleted_at IS NULL
629	  `;
630	}
631	
