  1	/**
  2	 * Business-context links for chat channels: typed `about` edges from a channel
  3	 * resource entity to org business entities (customer, project, company, …).
  4	 *
  5	 * ACL membership (`member_of`) and business context (`about`) share the same
  6	 * `entity_relationships` graph but use different relationship types — ACL
  7	 * reconcile never touches `about` edges.
  8	 */
  9	
 10	import { createLogger } from "@lobu/core";
 11	import { ACL_RESOURCE_TYPE_SLUG } from "@lobu/connector-sdk";
 12	import {
 13		type DbClient,
 14		getDb,
 15		pgBigintArray,
 16		pgTextArray,
 17	} from "../db/client.js";
 18	import { resolveEventAttributionsForItems } from "../utils/entity-link-upsert.js";
 19	import { ensureResourceEntityType } from "./access-graph.js";
 20	import { aclSourceFor, channelReadIdentityFor } from "./sources.js";
 21	
 22	const logger = createLogger("channel-about");
 23	
 24	export const ABOUT_RELATIONSHIP_SLUG = "about";
 25	export const ABOUT_EDGE_SOURCE_CONFIG = "config";
 26	export const ABOUT_EDGE_SOURCE_MANUAL = "manual";
 27	
 28	export interface ChannelAboutTarget {
 29		/** Bare or platform-prefixed channel id as stored on the binding. */
 30		channelId: string;
 31		/** The concrete workspace/tenant this channel lives in — the SAME real team
 32		 *  the subscription is keyed on (for Slack Grid: the workspace `T…`, NEVER the
 33		 *  enterprise `E…`). Resolved connector-side (`resolveSubscriptionTeam`) and threaded
 34		 *  in so the about edge attaches to the SAME channel resource entity the ACL
 35		 *  graph + subscription own. `null`/undefined = unknown yet (skip, heal from inbound)
 36		 *  for a team-scoped connector, mirroring the subscription's null-team behavior. */
 37		teamId: string | null | undefined;
 38		/** Resolved business-entity ids to link (channel --about--> each). */
 39		aboutEntityIds: number[];
 40	}
 41	
 42	export interface ChannelAboutMetadata {
 43		connection_id: string;
 44		channel_key: string;
 45	}
 46	
 47	/** Find-or-create the org-scoped `about` relationship type. */
 48	export async function ensureAboutRelationshipType(
 49		organizationId: string,
 50		sql: DbClient = getDb(),
 51	): Promise<number> {
 52		const existing = await findAboutRelationshipTypeId(organizationId, sql);
 53		if (existing !== null) return existing;
 54	
 55		const inserted = await sql<{ id: number }>`
 56		    INSERT INTO entity_relationship_types
 57		      (slug, name, description, organization_id, is_symmetric, created_by, created_at, updated_at)
 58		    VALUES
 59		      (${ABOUT_RELATIONSHIP_SLUG}, 'About', 'A chat channel is about a business entity',
 60		       ${organizationId}, false, NULL, current_timestamp, current_timestamp)
 61		    ON CONFLICT (organization_id, slug) WHERE status = 'active'
 62		    DO NOTHING
 63		    RETURNING id
 64		  `;
 65		if (inserted[0]) return Number(inserted[0].id);
 66	
 67		const raced = await findAboutRelationshipTypeId(organizationId, sql);
 68		if (raced !== null) return raced;
 69		throw new Error("Failed to initialize about relationship type");
 70	}
 71	
 72	async function findAboutRelationshipTypeId(
 73		organizationId: string,
 74		sql: DbClient,
 75	): Promise<number | null> {
 76		const rows = await sql<{ id: number }>`
 77	    SELECT id
 78	    FROM entity_relationship_types
 79	    WHERE organization_id = ${organizationId}
 80	      AND slug = ${ABOUT_RELATIONSHIP_SLUG}
 81	      AND status = 'active'
 82	      AND deleted_at IS NULL
 83	    LIMIT 1
 84	  `;
 85		return rows[0] ? Number(rows[0].id) : null;
 86	}
 87	
 88	/** Team-scoped resource key + identity namespace for a chat channel.
 89	 *
 90	 * Connector-agnostic: a connector that registers a `ChannelReadIdentity`
 91	 * contributes both its channel identity namespace and the exact team-scoped key
 92	 * construction the ACL sync writes, so this names no platform. Connectors with
 93	 * no registered chat gate fall back to the generic `chat_channel_id` form. */
 94	export function channelResourceIdentity(
 95		connectorKey: string,
 96		teamId: string | null | undefined,
 97		channelId: string,
 98	): { namespace: string; key: string } {
 99		const bare = channelId.includes(":")
100			? channelId.slice(channelId.indexOf(":") + 1)
101			: channelId;
102		const readIdentity = channelReadIdentityFor(connectorKey);
103		const key = readIdentity?.buildChannelKey(teamId, bare);
104		if (readIdentity && key) {
105			return { namespace: readIdentity.channelNamespace, key };
106		}
107		const team = teamId?.trim() || "";
108		return {
