114	/**
115	 * Ensure a channel resource entity exists (eager, before ACL sync). Returns the
116	 * entity id, or null when the key cannot be formed (e.g. a chat connector whose
117	 * team-scoped key needs a team id that wasn't supplied).
118	 */
119	export async function ensureChannelResourceEntity(opts: {
120		organizationId: string;
121		connectorKey: string;
122		teamId: string | null | undefined;
123		channelId: string;
124		displayName?: string | null;
125		sql?: DbClient;
126	}): Promise<number | null> {
127		const sql = opts.sql ?? getDb();
128		const bare = opts.channelId.includes(":")
129			? opts.channelId.slice(opts.channelId.indexOf(":") + 1)
130			: opts.channelId;
131		// A registered chat connector's key construction can refuse (return null) when
132		// its team-scoped key can't be formed — bail rather than materialize a bad
133		// resource under the generic fallback namespace.
134		const readIdentity = channelReadIdentityFor(opts.connectorKey);
135		if (readIdentity && readIdentity.buildChannelKey(opts.teamId, bare) === null) {
136			return null;
137		}
138		// Connector must register an ACL source; otherwise there is no resource to
139		// materialize.
140		const aclSource = aclSourceFor(opts.connectorKey);
141		if (!aclSource) return null;
142	
143		const { namespace, key } = channelResourceIdentity(
144			opts.connectorKey,
145			opts.teamId,
146			opts.channelId,
147		);
148		await ensureResourceEntityType(opts.organizationId);
149	
150		const resolved = await resolveEventAttributionsForItems(
151			{
152				connectorKey: opts.connectorKey,
153				orgId: opts.organizationId,
154				items: [
155					{
156						origin_type: "channel_about",
157						metadata: {
158							resource_key: key,
159							resource_name: opts.displayName ?? key,
160						},
161					},
162				],
163				rules: {
164					channel_about: [
165						{
166							role: "about",
167							entityType: ACL_RESOURCE_TYPE_SLUG,
168							autoCreate: true,
169							titlePath: "metadata.resource_name",
170							identities: [
171								{
172									namespace,
173									eventPath: "metadata.resource_key",
174									primary: true,
175								},
176							],
177						},
178					],
179				},
180			},
181			sql,
182		);
183		const ids = resolved.get(0);
184		return ids?.[0] ?? null;
185	}
