187	async function findChannelResourceEntityId(opts: {
188		organizationId: string;
189		connectorKey: string;
190		teamId: string | null | undefined;
191		channelId: string;
192		sql: DbClient;
193	}): Promise<number | null> {
194		if (opts.connectorKey === "slack" && !opts.teamId) return null;
195		const { namespace, key } = channelResourceIdentity(
196			opts.connectorKey,
197			opts.teamId,
198			opts.channelId,
