204	      ON e.id = ei.entity_id
205	     AND e.organization_id = ei.organization_id
206	     AND e.deleted_at IS NULL
207	    WHERE ei.organization_id = ${opts.organizationId}
208	      AND ei.namespace = ${namespace}
209	      AND ei.identifier = ${key}
210	      AND ei.deleted_at IS NULL
211	    LIMIT 1
212	  `;
213		return rows[0] ? Number(rows[0].id) : null;
