241	/** Normalize about targets: numbers pass through, strings resolve as slugs. */
242	export async function resolveAboutEntityRefs(
243		organizationId: string,
244		refs: Array<number | string>,
245		sql: DbClient = getDb(),
246	): Promise<number[]> {
247		const ids: number[] = [];
248		const slugs: string[] = [];
249		for (const ref of refs) {
250			if (typeof ref === "number" && Number.isFinite(ref)) ids.push(ref);
251			else if (typeof ref === "string" && ref.trim()) slugs.push(ref.trim());
252		}
253		const fromSlugs = await resolveEntitySlugsToIds(organizationId, slugs, sql);
254		return [...new Set([...ids, ...fromSlugs])];
255	}
