257	async function upsertAboutEdge(opts: {
258		organizationId: string;
259		fromChannelEntityId: number;
260		toBusinessEntityId: number;
261		source: string;
262		metadata: ChannelAboutMetadata;
263		userId: string | null | undefined;
264		typeId: number;
265		sql: DbClient;
266	}): Promise<void> {
267		await opts.sql`
268	    INSERT INTO entity_relationships (
269	      organization_id, from_entity_id, to_entity_id, relationship_type_id,
270	      metadata, confidence, source, created_by, updated_by, created_at, updated_at
271	    ) VALUES (
272	      ${opts.organizationId}, ${opts.fromChannelEntityId}, ${opts.toBusinessEntityId},
273	      ${opts.typeId}, ${opts.sql.json(opts.metadata)}, 1.0, ${opts.source},
274	      ${opts.userId ?? null}, ${opts.userId ?? null},
275	      current_timestamp, current_timestamp
276	    )
277	    ON CONFLICT (from_entity_id, to_entity_id, relationship_type_id)
278	      WHERE deleted_at IS NULL
279	    DO UPDATE SET
280	      metadata = EXCLUDED.metadata,
281	      source = EXCLUDED.source,
282	      updated_by = EXCLUDED.updated_by,
283	      updated_at = current_timestamp,
284	      deleted_at = NULL
285	  `;
