288	/**
289	 * Upsert config-sourced `about` edges for one connection and reconcile away
290	 * stale config edges (manual edges are never touched).
291	 */
292	export async function syncConnectionChannelAboutEdges(opts: {
293		organizationId: string;
294		connectionId: string | number;
295		connectorKey: string;
296		channels: ChannelAboutTarget[];
297		userId?: string | null;
298		sql?: DbClient;
299	}): Promise<{ linked: number; removed: number }> {
300		const sql = opts.sql ?? getDb();
301		const typeId = await ensureAboutRelationshipType(opts.organizationId, sql);
302		const connectionId = String(opts.connectionId);
303	
304		const desiredPairs = new Set<string>();
305		let linked = 0;
306	
307		for (const channel of opts.channels) {
308			const { key } = channelResourceIdentity(
309				opts.connectorKey,
310				channel.teamId,
311				channel.channelId,
312			);
313			const channelEntityId = await ensureChannelResourceEntity({
314				organizationId: opts.organizationId,
315				connectorKey: opts.connectorKey,
316				teamId: channel.teamId,
317				channelId: channel.channelId,
318				sql,
319			});
320			if (channelEntityId === null) {
321				logger.warn(
322					{
323						organization_id: opts.organizationId,
324						connection_id: connectionId,
325						channel_id: channel.channelId,
326					},
327					"Skipped channel about sync — channel entity could not be resolved",
328				);
329				continue;
330			}
331	
332			const metadata: ChannelAboutMetadata = {
333				connection_id: connectionId,
334				channel_key: key,
335			};
336	
337			for (const businessEntityId of channel.aboutEntityIds) {
338				const pairKey = `${channelEntityId}:${businessEntityId}`;
339				desiredPairs.add(pairKey);
340				await upsertAboutEdge({
341					organizationId: opts.organizationId,
342					fromChannelEntityId: channelEntityId,
343					toBusinessEntityId: businessEntityId,
344					source: ABOUT_EDGE_SOURCE_CONFIG,
345					metadata,
346					userId: opts.userId,
347					typeId,
348					sql,
349				});
350				linked += 1;
351			}
352		}
353	
354		const existing = await sql<{
355			id: number;
356			from_entity_id: number;
357			to_entity_id: number;
358		}>`
359	    SELECT r.id, r.from_entity_id, r.to_entity_id
360	    FROM entity_relationships r
361	    WHERE r.organization_id = ${opts.organizationId}
362	      AND r.relationship_type_id = ${typeId}
363	      AND r.source = ${ABOUT_EDGE_SOURCE_CONFIG}
364	      AND r.deleted_at IS NULL
365	      AND r.metadata->>'connection_id' = ${connectionId}
366	  `;
367	
368		let removed = 0;
369		for (const row of existing) {
370			const pairKey = `${Number(row.from_entity_id)}:${Number(row.to_entity_id)}`;
371			if (desiredPairs.has(pairKey)) continue;
372			await sql`
373	      UPDATE entity_relationships
374	      SET deleted_at = current_timestamp, updated_at = current_timestamp
375	      WHERE id = ${row.id}
376	    `;
377			removed += 1;
378		}
379	
380		return { linked, removed };
381	}
