421		const existing = await sql<{ id: number; to_entity_id: number }>`
422	    SELECT r.id, r.to_entity_id
423	    FROM entity_relationships r
424	    WHERE r.organization_id = ${opts.organizationId}
425	      AND r.from_entity_id = ${channelEntityId}
