441	      WHERE id = ${row.id}
442	    `;
443		}
444	
445		for (const businessEntityId of desired) {
446			await upsertAboutEdge({
447				organizationId: opts.organizationId,
448				fromChannelEntityId: channelEntityId,
449				toBusinessEntityId: businessEntityId,
450				source: ABOUT_EDGE_SOURCE_MANUAL,
451				metadata,
452				userId: opts.userId,
453				typeId,
454				sql,
455			});
456		}
457	}
