   560				// Update feed + run checkpoint if provided (so mid-run state like QR
   561				// codes surface in UI via recent_runs[0].checkpoint before the run
   562				// completes). No dry-run guard: on a dry run these write to the tx and
   563				// vanish with it, which is exactly right — advancing the feed checkpoint
   564				// would silently change what the NEXT real sync collects, making the
   565				// rows this run previewed unreachable.
   566				if (batch.checkpoint) {
   567					if (run.feed_id) {
   568						await db`
   569	      UPDATE feeds
   570	      SET checkpoint = ${db.json(batch.checkpoint)},
   571	          updated_at = current_timestamp
   572	      WHERE id = ${run.feed_id}
   573	    `;
   574					}
