   581	
   582				return { totalItems, rejectedItems };
   583			};
   584	
   585			// The real path: singleton handle, autocommit per statement, byte-for-byte
   586			// the behaviour that shipped before dry runs existed.
   587			//
   588			// The dry path: the same closure against a transaction, then an unconditional
   589			// rollback. postgres.js rolls back when the `begin` callback throws, so the
   590			// throw IS the mechanism — a sentinel, not an error condition. Catching only
   591			// that exact object means a genuine failure inside the batch still propagates
   592			// to the 500 handler below instead of being swallowed as "rolled back fine".
   593			const DRY_RUN_ROLLBACK = Symbol("dry-run-rollback");
   594			let outcome: Awaited<ReturnType<typeof ingestBatch>> | null = null;
   595			if (isDry) {
   596				try {
   597					await sql.begin(async (tx) => {
   598						outcome = await ingestBatch(tx);
   599						throw DRY_RUN_ROLLBACK;
   600					});
   601				} catch (err) {
   602					if (err !== DRY_RUN_ROLLBACK) throw err;
   603				}
   604			} else {
   605				outcome = await ingestBatch(sql);
   606			}
   607			// Unreachable: ingestBatch either assigns `outcome` or throws (and a throw
   608			// that is not the rollback sentinel is rethrown above). Asserted rather
   609			// than defaulted to {totalItems: 0} — TypeScript cannot see the assignment
   610			// through the transaction closure, and a silent zero here would report
   611			// "ingested nothing" for a batch that may well have ingested plenty.
   612			if (outcome === null) {
   613				throw new Error("[stream] batch completed without an outcome");
   614			}
   615			const { totalItems, rejectedItems } = outcome as Awaited<
   616				ReturnType<typeof ingestBatch>
   617			>;
   618	
   619			if (isDry) {
   620				// Written AFTER the rollback, on the singleton — this is the one thing a
   621				// dry run keeps, so it must not be inside the transaction it discards.
   622				// Accumulates across batches: a sync streams many, and the preview should
   623				// describe the whole run rather than only its last chunk. The per-batch
   624				// JS cap only bounds one request's payload, so the stored array is
   625				// re-capped here — without the ordinality slice a long sync would grow
   626				// the preview by up to DRY_RUN_PREVIEW_LIMIT per batch, unbounded.
   627				// `total` counts everything that would have been ingested even past the
