   641	            'truncated',
   642	            LEAST(
   643	              jsonb_array_length(
   644	                COALESCE(dry_run_preview -> 'items', '[]'::jsonb)
   645	                  || ${sql.json(dryPreview)}::jsonb
   646	              ),
   647	              ${DRY_RUN_PREVIEW_LIMIT}
   648	            ) < COALESCE((dry_run_preview ->> 'total')::int, 0) + ${totalItems}
