   667	/**
   668	 * POST /api/workers/complete
   669	 *
   670	 * Worker signals sync run completion (success or failure).
   671	 */
   672	export async function completeWorkerJob(c: Context<{ Bindings: Env }>) {
   673		try {
   674			const req = await c.req.json<CompleteRequest>();
   675	
   676			// Strip NUL (0x00) from connector-supplied jsonb payloads before they hit
   677			// Postgres (see streamContent). The final checkpoint and refreshed browser
   678			// auth_update are written via raw sql.json below.
