   680				req.checkpoint = stripNulDeep(req.checkpoint) as Record<string, unknown>;
   681			}
   682			if (req.auth_update) {
   683				req.auth_update = stripNulDeep(req.auth_update) as Record<
   684					string,
   685					unknown
   686				>;
   687			}
   688	
   689			const denied = await authorizeRunForWorker(c, req.run_id, req.worker_id);
   690			if (denied) return denied;
   691	
   692			const sql = getDb();
   693	
   694			// Atomic terminal-state transition with the shared F2 guard (see
   695			// finalizeRun). A no-op (0 rows) means the run was already finalized by
   696			// another path (e.g. the gateway reaped it on timeout and the worker is
   697			// reporting in late) or this worker isn't the claimant — without it a late
   698			// completion resurrects a reaped run and the feed/auth bookkeeping below
   699			// double-applies (consecutive_failures, items_collected, next_run_at,
   700			// auth_data). The failed path also stamps exit diagnostics.
   701			//
   702			// The checkpoint write is CASE-guarded on `dry_run` in SQL (rather than
   703			// read-then-branch in JS) so the guard rides the same atomic UPDATE as the
   704			// terminal transition: a dry run's row never records the connector's final
   705			// checkpoint, matching the streamContent guard on the mid-run write.
   706			const dryGuardedCheckpoint = sql`
   707	          checkpoint = CASE WHEN dry_run THEN checkpoint
   708	                       ELSE COALESCE(${req.checkpoint ? sql.json(req.checkpoint) : null}, checkpoint) END`;
   709			const updatedRuns = (await finalizeRun(sql, {
   710				runId: req.run_id,
   711				workerId: req.worker_id,
   712				status: req.status === "failed" ? "failed" : "completed",
   713				extraSet:
   714					req.status === "failed"
   715						? sql`,
   716	          items_collected = ${req.items_collected ?? 0},
   717	          error_message = ${req.error_message ?? null},${dryGuardedCheckpoint},
   718	          output_tail = ${req.output_tail ?? null},
   719	          exit_code = ${req.exit_code ?? null},
   720	          exit_signal = ${req.exit_signal ?? null},
   721	          exit_reason = ${req.exit_reason ?? null}`
   722						: sql`,
   723	          items_collected = ${req.items_collected ?? 0},
   724	          error_message = ${req.error_message ?? null},${dryGuardedCheckpoint}`,
   725				returning: sql`feed_id, connection_id, dry_run`,
   726			})) as unknown as Array<{
   727				feed_id: number | null;
   728				connection_id: number | null;
   729				dry_run: boolean;
   730			}>;
   731	
   732			if (updatedRuns.length === 0) {
   733				// The run was already finalized (timeout race) or this worker isn't the
   734				// claimant. Skip all feed/auth bookkeeping and return an idempotent
   735				// already-finalized response.
   736				logger.info(
   737					{
   738						run_id: req.run_id,
   739						worker_id: req.worker_id,
   740						claimed_status: req.status,
   741					},
   742					"[completeWorkerJob] no-op: run already in terminal state (likely gateway timeout)"
   743				);
   744				return c.json({ success: false, reason: "already_finalized" });
   745			}
   746	
   747			// Update the feed's sync state
   748			const runRows = updatedRuns;
   749			const feedId = runRows[0]?.feed_id;
   750			const isDry = runRows[0]?.dry_run === true;
   751	
   752			// Never for a dry run: this block stamps last_sync_at/status, resets or
   753			// increments consecutive_failures, adds items_collected, ADVANCES THE FEED
   754			// CHECKPOINT, and moves next_run_at (with backoff/auto-pause on failure).
   755			// Every one of those durably changes what the next REAL sync does or how
   756			// the feed reports its last real outcome — exactly the state a dry run
   757			// exists to leave untouched.
   758			//
   759			// Why this stays an explicit guard while streamContent uses a rolled-back
   760			// transaction instead. Two reasons, and they are the reasons — not an
   761			// oversight to be tidied up later:
   762			//
   763			//  1. This function's write set is closed and cannot grow the way an
   764			//     item-ingest loop grows: it finalizes one run row and stamps one feed
   765			//     row. One guard covers one block; there is no open set to lose track of.
   766			//  2. The keep/discard sets are INTERLEAVED. A dry run must still finalize
   767			//     its own run row — that is real working state, and finalizeRun's whole
   768			//     purpose is that the terminal transition is atomic. Rolling back here
   769			//     would mean lifting the run update out of the transaction and giving up
   770			//     that guarantee to buy uniformity. Not a trade worth making.
   771			if (feedId && !isDry) {
   772				const feedRows = (await sql`
   773	      SELECT schedule, timezone FROM feeds WHERE id = ${feedId}
   774	    `) as unknown as Array<{
   775					schedule: string | null;
   776					timezone: string | null;
   777				}>;
   778	
   779				// Manual feeds (no schedule) stay unscheduled after completion.
   780				const schedule = feedRows[0]?.schedule ?? null;
   781				const nextRun = schedule
   782					? nextRunAtFromCron(schedule, new Date(), feedRows[0]?.timezone ?? null)
   783					: null;
   784				const isSuccess = req.status === "success";
   785	
   786				// Failure rescheduling (item 5, #2033):
   787				//  - On success: reset consecutive_failures to 0 and use the plain cron
   788				//    next_run_at so a recovered feed immediately resumes normal cadence.
   789				//  - On failure: apply exponential backoff on top of the cron cadence so
   790				//    a persistently-failing feed retries progressively less often instead
   791				//    of re-enqueueing every plain cadence (which hammered the connector,
   792				//    the worker lane, and upstream rate limits). The backoff is computed
   793				//    from the NEW consecutive_failures count (post-increment) directly in
   794				//    SQL so it stays correct under concurrent completions across replicas.
