   145	export interface InsertedEvent {
   146	  id: number;
   147	  entity_ids: number[] | null;
   148	  origin_id: string;
   149	  title: string | null;
   150	  semantic_type: string;
   151	  created_at: string;
   152	  /** Whether this call landed a new immutable row or reused identical state. */
   153	  change: 'inserted' | 'superseded' | 'unchanged';
   154	}
   155	
   156	/** Key-order-independent JSON serialization for semantic equality checks. */
   157	export function stableJson(value: unknown): string {
   158	  if (value === null || typeof value !== 'object') return JSON.stringify(value);
   159	  if (Array.isArray(value)) return `[${value.map((item) => stableJson(item)).join(',')}]`;
   160	  const entries = Object.entries(value as Record<string, unknown>).sort(([a], [b]) =>
   161	    a.localeCompare(b)
   162	  );
   163	  return `{${entries.map(([k, v]) => `${JSON.stringify(k)}:${stableJson(v)}`).join(',')}}`;
   164	}
   165	
   166	function normalizedTimestamp(value?: Date | string | null): string | null {
   167	  if (!value) return null;
   168	  const date = value instanceof Date ? value : new Date(value);
   169	  if (Number.isNaN(date.getTime())) return null;
   170	  return date.toISOString();
   171	}
