   173	async function findCurrentEventByOrigin(
   174	  sql: DbClient,
   175	  params: InsertEventParams
   176	): Promise<
   177	  | {
   178	      id: number;
   179	      title: string | null;
   180	      payload_text: string | null;
   181	      payload_type: string;
   182	      payload_data: Record<string, unknown>;
   183	      payload_template: Record<string, unknown> | null;
   184	      attachments: unknown[];
   185	      author_name: string | null;
   186	      source_url: string | null;
   187	      occurred_at: string | null;
   188	      semantic_type: string;
   189	      origin_type: string | null;
   190	      metadata: Record<string, unknown>;
   191	      score: number | null;
   192	      origin_parent_id: string | null;
   193	      interaction_type: string;
   194	      interaction_status: string | null;
   195	      interaction_input_schema: Record<string, unknown> | null;
   196	      interaction_input: Record<string, unknown> | null;
   197	      interaction_output: Record<string, unknown> | null;
   198	      interaction_error: string | null;
   199	    }
   200	  | undefined
   201	> {
   202	  if (!params.connectionId || !params.originId) return undefined;
   203	
   204	  const rows = await sql`
   205	    SELECT e.id, e.title, e.payload_text, e.payload_type, e.payload_data, e.payload_template,
   206	           e.attachments, e.author_name, e.source_url, e.occurred_at, e.semantic_type, e.origin_type,
   207	           e.metadata, e.score, e.origin_parent_id, e.interaction_type, e.interaction_status,
   208	           e.interaction_input_schema, e.interaction_input, e.interaction_output, e.interaction_error
   209	    FROM events e
   210	    WHERE e.organization_id = ${params.organizationId}
   211	      AND e.connection_id = ${params.connectionId}
   212	      AND e.origin_id = ${params.originId}
   213	      AND NOT EXISTS (
   214	        SELECT 1 FROM events newer WHERE newer.supersedes_event_id = e.id
   215	      )
   216	    ORDER BY e.created_at DESC, e.id DESC
   217	    LIMIT 1
   218	  `;
   219	
   220	  return rows[0] as any;
   221	}
   222	
   223	function isSemanticallyEqual(
   224	  existing: NonNullable<Awaited<ReturnType<typeof findCurrentEventByOrigin>>>,
   225	  params: InsertEventParams
   226	): boolean {
   227	  return (
   228	    (existing.title ?? null) === (params.title ?? null) &&
   229	    (existing.payload_text ?? null) === (params.content ?? null) &&
   230	    existing.payload_type === (params.payloadType ?? 'text') &&
   231	    stableJson(existing.payload_data ?? {}) === stableJson(params.payloadData ?? {}) &&
   232	    stableJson(existing.payload_template ?? null) === stableJson(params.payloadTemplate ?? null) &&
   233	    stableJson(existing.attachments ?? []) === stableJson(params.attachments ?? []) &&
   234	    (existing.author_name ?? null) === (params.authorName ?? null) &&
   235	    (existing.source_url ?? null) === (params.sourceUrl ?? null) &&
   236	    // Only compare occurred_at when the caller supplied one. Insert defaults a
   237	    // missing occurred_at to now(), so an occurredAt-less re-upsert comparing
   238	    // null against the stamped default would supersede on every re-sync.
   239	    (params.occurredAt == null ||
   240	      normalizedTimestamp(existing.occurred_at ?? null) ===
   600	    // holds the inverse of `supersedes_event_id`: we stamp the row we just
   601	    // replaced with the id of THIS new superseding row so live-row reads can
   602	    // one day use `WHERE superseded_by IS NULL` instead of the per-row
   603	    // anti-join in current_event_records. This touches LINEAGE METADATA ONLY,
   604	    // never payload — the append-only invariant applies to content (precedent:
   605	    // search_tsv is likewise maintained post-insert). Runs on the SAME `sql`
   606	    // handle as the INSERT, so when we're inside the dedup advisory-lock tx or
   607	    // a caller-supplied tx (identity engine) it is atomic with the supersede.
   608	    //
   609	    // The `AND superseded_by IS NULL` guard is belt-and-braces: the partial
   610	    // unique index idx_events_superseded_by already fired a 23505 on the INSERT
   611	    // above if the target was already superseded, so a 0-row UPDATE here can
   612	    // only happen if the column was backfilled/stamped by a losing concurrent
   613	    // writer whose INSERT nonetheless slipped through — in which case leaving
   614	    // the existing stamp intact is correct (the unique index still guarantees a
   615	    // single superseder).
