   631	    return persisted;
   632	  };
   633	
   634	  // The dedup path (onConflictUpdate) is a non-atomic read-then-insert: it
   635	  // looks up the current row for (connection_id, origin_id), then either
   636	  // supersedes it or inserts fresh. Without serialization, two concurrent
   637	  // ingests of the SAME item — common under N>1 app replicas and even two
   638	  // overlapping runs on one replica — can both see "no current row" and both
   639	  // insert with supersedes_event_id NULL (→ permanent duplicate current rows),
   640	  // or both target the same row to supersede (→ duplicate-key error on
   641	  // idx_events_superseded_by, which fails the whole stream batch). Hold a
   642	  // transaction-scoped advisory lock keyed on (connection_id, origin_id) so
   643	  // these serialize. Only engage when we own the connection (no caller-supplied
   644	  // tx, which already runs in its own atomic scope) and have both keys.
   645	  if (options?.onConflictUpdate && !options.sql && params.connectionId && params.originId) {
   646	    const lockKey = eventDedupLockKey(params.connectionId, params.originId);
   647	    return sql.begin(async (tx) => {
   648	      await tx`
   649	        SELECT pg_advisory_xact_lock(${EVENT_DEDUP_LOCK_NAMESPACE}, ${lockKey})
   650	      `;
   651	      return runInsert(tx);
   652	    }) as Promise<InsertedEvent>;
   653	  }
   654	
   655	  // An explicit supersede without a caller-supplied tx must still commit the
   656	  // superseding INSERT and the superseded_by stamp atomically: as two
   657	  // autocommit statements, a crash between them would leave the superseded
   658	  // row's denormalized edge permanently NULL — which, after the Stage-2 view
   659	  // flip to `WHERE superseded_by IS NULL`, would resurrect it as a live row.
   660	  // (The dedup path can only derive a supersede when connectionId+originId are
   661	  // both present, and that case is already inside the advisory-lock tx above.)
   662	  if (params.supersedesEventId != null && !options?.sql) {
   663	    return sql.begin(async (tx) =>
   664	      runInsert(tx)
   665	    ) as Promise<InsertedEvent>;
   666	  }
   667	
   668	  return runInsert(sql);
   669	}
