   671	// ============================================
   672	// Change Event (fire-and-forget audit trail)
   673	// ============================================
   674	
   675	interface ChangeEventParams {
   676	  entityIds: number[];
   677	  organizationId: string;
   678	  title: string;
   679	  content: string;
   680	  metadata: Record<string, unknown>;
   681	  createdBy?: string | null;
   682	  clientId?: string | null;
   683	}
   684	
   685	const AUDIT_IDEMPOTENCY_INDEX = 'idx_events_org_idempotency_key';
   686	
   687	/**
   688	 * Persist a connectionless audit/change event with DB-enforced idempotency.
   689	 *
   690	 * Fire-and-forget writers retry with the same originId after a transient
   691	 * failure. Connector-sourced rows use a unique (connection_id, origin_id)
   692	 * path; connectionless audit rows do not. Stamp the reserved
   693	 * `_lobu_idempotency_key` (unique per org via `idx_events_org_idempotency_key`)
   694	 * so a concurrent or retry insert after an ambiguous success resolves to the
   695	 * winner instead of appending a duplicate.
   696	 */
   697	export async function insertConnectionlessAuditEvent(
   698	  params: InsertEventParams
   699	): Promise<InsertedEvent> {
   700	  const idempotencyKey = `audit:${params.originId}`;
   701	  const metadata: Record<string, unknown> = {
   702	    ...(params.metadata ?? {}),
   703	    _lobu_idempotency_key: idempotencyKey,
   704	  };
   705	
   706	  try {
   707	    return await insertEvent({
   708	      ...params,
   709	      connectionId: null,
   710	      metadata,
   711	    });
   712	  } catch (error) {
   713	    if (!isUniqueViolation(error, AUDIT_IDEMPOTENCY_INDEX)) throw error;
   714	    const sql = getDb();
   715	    const existing = await sql`
   716	      SELECT id, entity_ids, origin_id, title, semantic_type, created_at
   717	      FROM events
   718	      WHERE organization_id = ${params.organizationId}
   719	        AND metadata ? '_lobu_idempotency_key'
   720	        AND metadata->>'_lobu_idempotency_key' = ${idempotencyKey}
   721	      ORDER BY id ASC
   722	      LIMIT 1
   723	    `;
   724	    if (!existing[0]) throw error;
   725	    const row = existing[0] as {
   726	      id: number | string;
   727	      entity_ids: number[] | null;
   728	      origin_id: string;
   729	      title: string | null;
   730	      semantic_type: string;
   731	      created_at: string;
   732	    };
   733	    return {
   734	      id: Number(row.id),
   735	      entity_ids: row.entity_ids,
   736	      origin_id: row.origin_id,
   737	      title: row.title,
   738	      semantic_type: row.semantic_type,
   739	      created_at: row.created_at,
   740	      change: 'unchanged',
   741	    };
   742	  }
   743	}
   744	
   745	/**
   746	 * Record a change event for audit purposes.
   747	 *
   748	 * Fire-and-forget — never throws. Retries once after a short delay; the same
   749	 * originId is reconciled before re-insert so an ambiguous success cannot
