   751	 * at ERROR with full event context so it's visible in alerting rather than
   752	 * silently lost. Used for entity updates, watcher archival, connection/feed
   753	 * deletion, etc.
   754	 */
   755	export function recordChangeEvent(params: ChangeEventParams): void {
   756	  if (params.entityIds.length === 0) return;
   757	
   758	  const externalId = `change_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
   759	
   760	  retryWithBackoff(
   761	    () =>
   762	      insertConnectionlessAuditEvent({
   763	        entityIds: params.entityIds,
   764	        organizationId: params.organizationId,
   765	        originId: externalId,
   766	        title: params.title,
   767	        content: params.content,
   768	        semanticType: 'change',
   769	        metadata: params.metadata,
   770	        createdBy: params.createdBy ?? null,
   771	        clientId: params.clientId ?? null,
   772	      }),
   773	    AUDIT_EVENT_RETRY
   774	  ).catch((err) => {
   775	    logger.error(
   776	      {
   777	        err,
   778	        originId: externalId,
   779	        organizationId: params.organizationId,
   780	        entityIds: params.entityIds,
   781	        title: params.title,
   782	        metadata: params.metadata,
   783	      },
   784	      '[insert-event] change audit event DROPPED after retry — audit trail is missing this row'
   785	    );
   786	  });
   787	}
