373	/**
374	 * Insert a single event into the events table.
375	 *
376	 * Returns the inserted row (id, entity_ids, title, semantic_type, created_at).
377	 * If `onConflictUpdate` is true, performs an upsert on (connection_id, origin_id).
378	 * If `sql` is passed, the insert runs on that (transaction-bound) handle
379	 * instead of the singleton pool — used by the identity engine to keep its
380	 * fact + derivation writes atomic.
381	 */
382	export async function insertEvent(
383	  params: InsertEventParams,
384	  options?: {
385	    onConflictUpdate?: boolean;
386	    sql?: DbClient;
387	    /** Transactional hook for durable derived work such as Behavior runs. */
388	    afterPersist?: (event: InsertedEvent, sql: DbClient) => Promise<void>;
389	  }
390	): Promise<InsertedEvent> {
391	  const sql = options?.sql ?? getDb();
392	
393	  // Reverse-geocode lat/lng → city / admin1 / country once per event,
394	  // before insert. Silent no-op when the connector hasn't supplied
395	  // coordinates, when PostGIS / geo_places aren't seeded, or when the
396	  // nearest place is too far (ocean / desert). Connector-supplied
397	  // place_name etc. are preserved — enrichment only fills gaps.
398	  const enrichment = await lookupGeoEnrichment(params.metadata, { sql });
399	  const enrichedMetadata = mergeEnrichedMetadata(params.metadata, enrichment);
400	  if (enrichedMetadata !== params.metadata) {
401	    params = { ...params, metadata: enrichedMetadata };
402	  }
403	
404	  const entityIdsValue = params.entityIds.length > 0 ? `{${params.entityIds.join(',')}}` : null;
405	
406	  const requestedClientId = params.clientId ?? null;
407	
408	  // Core find→decide→insert, parameterized on the active SQL handle so it can
409	  // run either directly on the singleton pool or inside the dedup transaction
410	  // below (which holds an advisory lock for the duration).
411	  const runInsert = async (
412	    activeSql: DbClient
413	  ): Promise<InsertedEvent> => {
414	    let supersedesEventId = params.supersedesEventId ?? null;
415	
416	    if (options?.onConflictUpdate) {
417	      const existing = await findCurrentEventByOrigin(activeSql, params);
418	      if (existing) {
419	        if (isSemanticallyEqual(existing, params)) {
420	          // Reread before touching the embedding. If the row got
421	          // deleted / tombstoned between findCurrentEventByOrigin and
422	          // here, upsertEmbedding would FK-fail instead of letting us
423	          // fall through cleanly to a fresh insert (CodeRabbit catch
424	          // on PR #780).
425	          const existingRows = await activeSql`
426	            SELECT id, entity_ids, origin_id, title, semantic_type, created_at
427	            FROM events
428	            WHERE id = ${existing.id}
429	            LIMIT 1
430	          `;
431	          const existingRow = existingRows[0] as InsertedEvent | undefined;
432	          if (existingRow) {
433	            await upsertEmbedding(
434	              existingRow.id,
435	              params.embedding,
436	              params.embeddingModel,
437	              activeSql
438	            );
439	            const unchanged = { ...existingRow, change: 'unchanged' as const };
440	            await options?.afterPersist?.(unchanged, activeSql);
441	            return unchanged;
442	          }
443	          // Race: the existing row was deleted/tombstoned between the
444	          // findCurrentEventByOrigin lookup above and the SELECT here. Fall
445	          // through into the INSERT path with `supersedesEventId` unset so we
446	          // create a fresh row instead of crashing on `undefined.id`.
447	          logger.warn(
448	            { existingId: existing.id, originId: params.originId },
449	            '[insert-event] existing row vanished between find and reread — proceeding with fresh insert'
450	          );
451	        } else {
452	          supersedesEventId = existing.id;
453	        }
454	      }
455	    }

